import datetime
import sys
import textwrap
import os
import random

start_time = datetime.datetime.now()
print(f'{" Start ":=^79}')


version = "1.0.2"
script_basename = os.path.splitext(os.path.basename(sys.argv[0]))[0]
script_path = os.path.dirname(os.path.realpath(sys.argv[0]))
bin_dir = script_path
work_dir = os.path.dirname(script_path)
input_dir = os.path.join(work_dir, 'input')
output_dir = os.path.join(work_dir, 'output', script_basename)
sub_script_dir = os.path.join(bin_dir, script_basename)

# Ensure output directory exists
os.makedirs(output_dir, exist_ok=True)
os.makedirs(sub_script_dir, exist_ok=True)


# Function to wrap text to 79 characters
def wrap79(text, width=79):
    return textwrap.fill(text, width=width, subsequent_indent=' '*4)


# Read individual, population and haplotype number list
with open(os.path.join(input_dir,
                       "s01.random_individual_population.txt"), 'r') as fi:
    record_dic = {}    # {REP1: [{POP1:[ind1,ind2,ind3]}], REP2: [POP3, POP4]}
    repeats = []
    populations = []
    for line in fi:
        line = line.strip()
        if line.startswith('#') or line == '':
            continue
        else:
            Individual, Population, Individual_number, Haplotype1_number, Haplotype2_number, Repeat_number \
                = line.split('\t')

            populations.append(
                Population) if Population not in populations else None

            reps = Repeat_number.split(',')
            for rep in reps:
                if rep not in repeats:
                    repeats.append(rep)
                record_dic[rep] = record_dic.get(rep, {})
                record_dic[rep][Population] = record_dic[rep].get(
                    Population, [])
                record_dic[rep][Population].extend(
                    [Haplotype1_number, Haplotype2_number])
            del rep, reps


# Read the chromosome list
with open(os.path.join(input_dir, "s02.chromosome_list.txt"), 'r') as fi:
    chrs = [line.strip() for line in fi]


# Function, haplotype number to string
def hap_num_to_random_str(hap_nums_pop1, hap_nums_pop2):
    hap_pairs = []
    for m in hap_nums_pop1:
        for n in hap_nums_pop2:
            if m == n:       # For development, this situation should not arise
                raise ValueError(
                    f'Haplotype number {m} is duplicated in two populations')
            hap_pair = f'{m}-{n}'
            if hap_pair not in hap_pairs:
                hap_pairs.append(hap_pair)
            else:            # For development, this situation should not arise
                raise ValueError(f'Duplicated haplotype pair: {hap_pair}')

    # Random return 10 haplotype pairs
    random_hap_pairs = random.sample(hap_pairs, 10)
    hap_str = ','.join(random_hap_pairs)
    return hap_str


# Write MSMC2 running script
header = f'''#!/usr/bin/env bash
# This script was generated by {script_basename}.py
# {version}
# on {start_time}
'''

for rep_a in repeats:
    # for rep_b in repeats:
    for pop_m in range(len(populations)-1):
        for pop_n in range(pop_m+1, len(populations)):
            pop1 = populations[pop_m]
            pop2 = populations[pop_n]
            # Define the input file list
            multihetsep_files = [os.path.join(work_dir, "output",
                                              's03.generate_multihetsep',
                                              f'{chr}.{rep_a}.multihetsep.txt') for chr in chrs]
            multihetsep_files = ' \\\n    '.join(multihetsep_files)

            # Define the output script for running msmc2
            # From v1.0.1. Not support run rep_a != rep_b, because the input files are generated by the same repeat number respectively.
            out_script_base = f's05.{pop1}.{rep_a}.{pop2}.{rep_a}.run_MSMC2'
            out_script = os.path.join(
                sub_script_dir, f'{out_script_base}.sh')
            if os.path.exists(out_script):
                print(f'{out_script} exists, skip')
                continue

            # Define the output file for msmc2
            msmc2_output = os.path.join(
                output_dir, f'{pop1}.{rep_a}.{pop2}.{rep_a}.msmc2')

            if os.path.exists(msmc2_output):
                print(f'{msmc2_output} exists, skip')
                continue
            with open(f'{out_script}', 'w') as f:
                f.write(f'{header}')
                f.write(f'''
#SBATCH -J {out_script_base}
#SBATCH -o {out_script_base}.%J.out
#SBATCH -e {out_script_base}.%J.err
#SBATCH -c 16
#SBATCH --mem=120G

source {os.path.join(bin_dir,'s00.load_environment.sh')}

msmc2_Linux \\
    -t 16 \\
    -i 20 \\
    -p 1*2+40*1+1*2 \\
    -I {hap_num_to_random_str(record_dic[rep_a][pop1],record_dic[rep_a][pop2])} \\
    -o {msmc2_output} \\
    {multihetsep_files}
''')


end_time = datetime.datetime.now()
print('')
print(' END '.center(79, '='))
print(str(end_time-start_time).center(79))
